 private static final class Access implements QrCameraAccess.Port {QrCameraAccess.Status status=QrCameraAccess.Status.NEEDED;int requests;boolean fail;public QrCameraAccess.Status status(Activity a){return status;}public void request(Activity a){requests++;if(fail)throw new IllegalStateException("fixture");}}
 private static final class Camera implements QrCamera.Port {final View view;QrScanSession.Listener listener;int starts,closes;Camera(ComponentActivity a){view=new View(a);view.setBackgroundColor(Design.SOFT);view.setContentDescription("Injected camera preview");}public View preview(){return view;}public void start(QrScanSession.Listener l){listener=l;starts++;}public void close(){closes++;}}
 private static final class TagAccess implements MorningTagSetup.Port {
  final SharedPreferences preferences;final List<java.util.function.Consumer<byte[]>> callbacks=new CopyOnWriteArrayList<>();MorningTagSetup.Availability state=MorningTagSetup.Availability.READY;boolean readFailure,settingsFailure;int stops,settings;Activity readerOwner;NfcEnrollment latest;
  TagAccess(SharedPreferences preferences){this.preferences=preferences;}
  public SharedPreferences preferences(Activity owner){if(readFailure)throw new IllegalStateException("private fixture read failure");return preferences;}
  public MorningTagSetup.Availability availability(Activity owner){return state;}
  public void settings(Activity owner){settings++;if(settingsFailure)throw new IllegalStateException("private settings fixture");}
  public NfcEnrollment enrollment(Activity owner,java.util.function.Consumer<String> captured,java.util.function.Consumer<String> notice){readerOwner=owner;latest=new NfcEnrollment(owner,new NfcEnrollment.Reader(){public boolean ready(){return state==MorningTagSetup.Availability.READY;}public void start(java.util.function.Consumer<byte[]> found){callbacks.add(found);}public void stop(){stops++;}},captured,notice);return latest;}
 }
 private TagAccess tags;private Activity catalogOwner;private int catalogScrollY;private String catalogQuery;
 private Dialog dialog(Object holder,String name){try{java.lang.reflect.Field field=holder.getClass().getDeclaredField(name);field.setAccessible(true);return(Dialog)field.get(holder);}catch(ReflectiveOperationException failure){throw new AssertionError("Actual owned dialog field "+name,failure);}}
 private View ownedWindow(){Activity owner=current;if(owner==null||owner.isDestroyed())return null;if(owner instanceof QrCodeActivity){Dialog menu=dialog(owner,"formatDialog");if(menu!=null&&menu.isShowing())return menu.getWindow().getDecorView();if(tags!=null&&tags.readerOwner==owner&&tags.latest!=null){Dialog reader=dialog(tags.latest,"dialog");if(reader!=null&&reader.isShowing())return reader.getWindow().getDecorView();}}return owner.getWindow().getDecorView();}
 private View find(View root,String label){ArrayList<View> matches=new ArrayList<>();root.findViewsWithText(matches,label,View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);for(View view:matches)if(label.contentEquals(view.getContentDescription()))return view;matches.clear();root.findViewsWithText(matches,label,View.FIND_VIEWS_WITH_TEXT);for(View view:matches)if(view instanceof android.widget.TextView text&&label.contentEquals(text.getText().toString().replace("\uFFFC","").strip()))return view;return null;}
 private android.widget.ScrollView scroller(View view){if(view instanceof android.widget.ScrollView)return(android.widget.ScrollView)view;if(view instanceof android.view.ViewGroup group)for(int n=0;n<group.getChildCount();n++){android.widget.ScrollView found=scroller(group.getChildAt(n));if(found!=null)return found;}return null;}
 private boolean fullyVisible(View view){if(view==null)return false;android.graphics.Rect bounds=new android.graphics.Rect();return view.isShown()&&view.getGlobalVisibleRect(bounds)&&bounds.width()==view.getWidth()&&bounds.height()==view.getHeight();}
 private android.graphics.Rect screenBounds(View view){android.graphics.Rect bounds=new android.graphics.Rect();assertTrue("Actual view has a local visible rectangle",view.getLocalVisibleRect(bounds));int[] origin=new int[2];view.getLocationOnScreen(origin);bounds.offset(origin[0],origin[1]);return bounds;}
 private void full(View view,String label){assertTrue(label+" fully visible",fullyVisible(view));assertTrue(label+" full 48dp width",view.getWidth()>=Design.dp(c,48));assertTrue(label+" full 48dp height",view.getHeight()>=Design.dp(c,48));}
 private void committed(View root)throws Exception{CountDownLatch frame=new CountDownLatch(1);i.runOnMainSync(()->{assertSame(root,ownedWindow());assertTrue(root.isAttachedToWindow()&&root.hasWindowFocus()&&root.isHardwareAccelerated());root.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);root.invalidate();});assertTrue("Actual owned frame commits",frame.await(5,TimeUnit.SECONDS));}
 private View reveal(String label)throws Exception{
  View[] accepted=new View[2];awaitAction(()->{View root=ownedWindow();if(root==null||!root.hasWindowFocus()||!root.isAttachedToWindow()||!root.isLaidOut())return false;View target=find(root,label);while(target!=null&&!target.isClickable()&&!(target instanceof android.widget.EditText))target=target.getParent() instanceof View?(View)target.getParent():null;if(target==null||!target.isLaidOut())return false;accepted[0]=root;accepted[1]=target;return true;},"focused owned target "+label);
  for(int n=0;n<4;n++){boolean[] full={false};android.graphics.Rect bounds=new android.graphics.Rect();int[] position=new int[2];i.runOnMainSync(()->{assertSame(accepted[0],ownedWindow());full[0]=fullyVisible(accepted[1]);if(!full[0]){android.widget.ScrollView scroll=scroller(accepted[0]);assertNotNull("Actual scroll owner",scroll);bounds.set(screenBounds(scroll));accepted[1].getLocationOnScreen(position);}});if(full[0])break;boolean below=position[1]>=bounds.centerY();assertTrue("One actual scroll toward "+label,device.swipe(bounds.centerX(),below?bounds.bottom-Design.dp(c,20):bounds.top+Design.dp(c,20),bounds.centerX(),below?bounds.top+Design.dp(c,20):bounds.bottom-Design.dp(c,20),20));device.waitForIdle();}
  committed(accepted[0]);i.runOnMainSync(()->{assertSame(accepted[0],ownedWindow());full(accepted[1],label);});return accepted[1];
 }
 private void ownedTap(String label)throws Exception{View target=reveal(label);android.graphics.Rect bounds=new android.graphics.Rect();i.runOnMainSync(()->{assertTrue(target.isAttachedToWindow()&&target.hasWindowFocus()&&target.isEnabled());full(target,label);bounds.set(screenBounds(target));assertEquals(target.getWidth(),bounds.width());assertEquals(target.getHeight(),bounds.height());if(label.equals("Configure QR code")){catalogOwner=current;catalogScrollY=scroller(ownedWindow()).getScrollY();View search=find(ownedWindow(),"Search task types");assertTrue(search instanceof android.widget.EditText);catalogQuery=((android.widget.EditText)search).getText().toString();}System.out.println("OWNED_ENROLLMENT_ACTION "+label+" screen="+bounds);});assertTrue("Exactly one real coordinate tap "+label,device.click(bounds.centerX(),bounds.centerY()));}
 private void textOnOwner(String text){awaitAction(()->{View root=ownedWindow();return root!=null&&root.hasWindowFocus()&&find(root,text)!=null;},"owned text "+text);}
