  ownedTap("Read bedside NFC tag");awaitAction(()->tags.latest!=null&&tags.latest.active(),"first explicitly owned NFC reader");java.util.function.Consumer<byte[]> canceled=tags.callbacks.get(tags.callbacks.size()-1);ownedTap("Cancel");
  awaitAction(()->current.hasWindowFocus()&&ownedWindow()==current.getWindow().getDecorView(),"NFC page regained focus after cancel");i.runOnMainSync(()->canceled.accept(new byte[]{9,9}));i.waitForIdleSync();assertEquals(original,tags.preferences.getString(MorningTagSetup.KEY,""));
