 private void recreate(String text)throws Exception{Activity old=current;Class<?> type=old.getClass();Activity[] next={null};Instrumentation.ActivityMonitor m=i.addMonitor(type.getName(),null,false);try{i.runOnMainSync(old::recreate);next[0]=m.waitForActivityWithTimeout(5000);assertNotNull(next[0]);}finally{i.removeMonitor(m);}awaitAction(()->{if(current!=next[0]||!old.isDestroyed())return false;if(text.equals("Code type")){Dialog menu=dialog(current,"formatDialog");if(menu==null||!menu.isShowing())return false;}View root=ownedWindow();return root!=null&&root.hasWindowFocus()&&root.isLaidOut()&&find(root,text)!=null;},"actual recreated owner "+text);}
 private void capture(String suffix)throws Exception{View[] capturedRoot={null};CountDownLatch frame=new CountDownLatch(1);boolean[] registered={false};long until=SystemClock.elapsedRealtime()+5000;while(!registered[0]&&SystemClock.elapsedRealtime()<until){i.runOnMainSync(()->{Activity a=current;if(a!=null&&!a.isDestroyed()){View decor=ownedWindow();if(decor!=null&&decor.hasWindowFocus()&&decor.isLaidOut()&&decor.isAttachedToWindow()&&decor.isHardwareAccelerated()){capturedRoot[0]=decor;decor.getViewTreeObserver().registerFrameCommitCallback(frame::countDown);decor.invalidate();registered[0]=true;}}});if(!registered[0])SystemClock.sleep(50);}assertTrue("Focused QR configuration window",registered[0]);assertTrue(frame.await(5,TimeUnit.SECONDS));i.runOnMainSync(()->{assertSame("Captured window is still the actual owner",capturedRoot[0],ownedWindow());assertTrue(capturedRoot[0].hasWindowFocus());if(suffix.equals("types-recreated")){assertTrue(dialog(current,"formatDialog").isShowing());full(find(capturedRoot[0],"Choose Code 39"),"Selected Code 39 option");full(find(capturedRoot[0],"Cancel"),"Owned code-type Cancel");}if(suffix.startsWith("nfc-"))nfcBounds(suffix,capturedRoot[0]);});if(suffix.startsWith("fallback"))i.runOnMainSync(()->{for(String operator:List.of("Addition","Subtraction","Multiplication","Division")){ArrayList<View> cards=new ArrayList<>();current.getWindow().getDecorView().findViewsWithText(cards,operator,View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);assertEquals(operator+" has one card",1,cards.size());View card=cards.get(0),row=(View)card.getParent();assertTrue(operator+" upper border stays within row",card.getTop()>=row.getPaddingTop());assertTrue(operator+" lower border stays within row",card.getBottom()<=row.getHeight()-row.getPaddingBottom());}});if(suffix.equals("captured")||suffix.equals("unavailable"))i.runOnMainSync(()->{
  View root=current.getWindow().getDecorView();ArrayList<View> rows=new ArrayList<>(),buttons=new ArrayList<>();
  root.findViewsWithText(rows,"Fallback task",View.FIND_VIEWS_WITH_CONTENT_DESCRIPTION);root.findViewsWithText(buttons,"Save code",View.FIND_VIEWS_WITH_TEXT);
  assertEquals("Exactly one real fallback row",1,rows.size());assertEquals("Exactly one real Save code action",1,buttons.size());
  View row=rows.get(0),save=buttons.get(0);android.graphics.Rect rowBounds=new android.graphics.Rect(),saveBounds=new android.graphics.Rect();
  assertTrue("Fallback row is visible",row.getGlobalVisibleRect(rowBounds));assertEquals("Complete fallback row height",row.getHeight(),rowBounds.height());assertEquals("Complete fallback row width",row.getWidth(),rowBounds.width());
  assertTrue("Save code is visible",save.getGlobalVisibleRect(saveBounds));assertEquals("Complete Save code height",save.getHeight(),saveBounds.height());assertEquals("Complete Save code width",save.getWidth(),saveBounds.width());
  assertTrue("Fallback subtitle fits above fixed Save without scrolling",rowBounds.bottom<=saveBounds.top);
  assertTrue("Fallback retains 48dp target",rowBounds.height()>=Design.dp(c,48)&&rowBounds.width()>=Design.dp(c,48));assertTrue("Save retains 48dp target",saveBounds.height()>=Design.dp(c,48)&&saveBounds.width()>=Design.dp(c,48));
  for(String tag:List.of("qr-print-action","qr-scan-action")){
   View action=root.findViewWithTag(tag);assertNotNull(tag,action);android.graphics.Rect bounds=new android.graphics.Rect();assertTrue(tag+" visible",action.getGlobalVisibleRect(bounds));
   assertEquals(tag+" full height",action.getHeight(),bounds.height());assertEquals(tag+" full width",action.getWidth(),bounds.width());assertTrue(tag+" 48dp target",bounds.width()>=Design.dp(c,48)&&bounds.height()>=Design.dp(c,48));
  }
 });File folder=new File(c.getExternalFilesDir(null),"verification");assertTrue(folder.isDirectory()||folder.mkdirs());assertTrue(device.takeScreenshot(new File(folder,"qr-code-"+suffix+".png")));}
 private String decoded(String payload)throws Exception{int size=320;BitMatrix matrix=new QRCodeWriter().encode(payload,BarcodeFormat.QR_CODE,size,size,Map.of(EncodeHintType.CHARACTER_SET,"UTF-8"));byte[] pixels=new byte[size*size];for(int y=0;y<size;y++)for(int x=0;x<size;x++)pixels[y*size+x]=(byte)(matrix.get(x,y)?0:255);String hash=new QrDecoder().digest(pixels,size,size);assertEquals(MorningCode.digest(payload),hash);return hash;}
 private void awaitAction(java.util.function.BooleanSupplier expected,String label){boolean[] ready={false};long end=SystemClock.elapsedRealtime()+5000;do{i.runOnMainSync(()->ready[0]=expected.getAsBoolean());if(!ready[0])SystemClock.sleep(25);}while(!ready[0]&&SystemClock.elapsedRealtime()<end);assertTrue("Actual main-thread action: "+label,ready[0]);}
 private void nfcDialogOwnership()throws Exception{Activity owner=current;List<java.util.function.Consumer<byte[]>> callbacks=new ArrayList<>();java.util.concurrent.atomic.AtomicReference<String> saved=new java.util.concurrent.atomic.AtomicReference<>("previous-tag");int[] stops={0};NfcEnrollment[] enrollment={null};i.runOnMainSync(()->{enrollment[0]=new NfcEnrollment(owner,new NfcEnrollment.Reader(){public boolean ready(){return true;}public void start(java.util.function.Consumer<byte[]> found){callbacks.add(found);}public void stop(){stops[0]++;}},saved::set,message->{});enrollment[0].open();});try{awaitAction(()->enrollment[0].active(),"focused fake NFC enrollment");i.runOnMainSync(()->{callbacks.get(0).accept(new byte[]{1,2});enrollment[0].close();});i.waitForIdleSync();assertEquals("Canceled queued tag must not overwrite enrollment","previous-tag",saved.get());awaitAction(()->current==owner&&!owner.isFinishing()&&!owner.isDestroyed()&&owner.hasWindowFocus(),"original QR owner regained focus after canceled NFC dialog");i.runOnMainSync(enrollment[0]::open);awaitAction(()->enrollment[0].active(),"replacement fake NFC enrollment");i.runOnMainSync(()->callbacks.get(0).accept(new byte[]{3,4}));i.waitForIdleSync();assertEquals("Old reader must not enroll into a new dialog","previous-tag",saved.get());i.runOnMainSync(()->callbacks.get(1).accept(new byte[]{5,6}));awaitAction(()->saved.get().equals(AlarmActivity.hex(new byte[]{5,6})),"current fake NFC tag accepted");assertEquals(2,stops[0]);}finally{i.runOnMainSync(enrollment[0]::close);}}
