 private void assertBadImports(Store store,Alarm saved,Alarm other)throws Exception{JSONObject valid=MorningCodeJson.encode(saved.challenges().tasks.get(1).code);List<Object> bad=new ArrayList<>();bad.add(JSONObject.NULL);bad.add("bathroom");bad.add(new JSONObject(valid.toString()).put("hash","not-a-hash"));bad.add(new JSONObject(valid.toString()).put("hash",valid.getString("hash").toUpperCase(Locale.ROOT)));bad.add(new JSONObject(valid.toString()).put("label"," Bathroom "));bad.add(new JSONObject(valid.toString()).put("label",1));bad.add(new JSONObject(valid.toString()).put("fallback",JSONObject.NULL));bad.add(new JSONObject(valid.toString()).put("raw", "forbidden"));bad.add(new JSONObject(valid.toString()).put("fallback",new JSONObject().put("level","hard").put("operators",new JSONArray().put("divide")).put("answer","voice")));String before=store.backup().toString();for(Object value:bad){JSONArray tasks=ChallengeRoutineJson.encode(saved.challenges());tasks.getJSONObject(1).put("code",value);JSONObject source=saved.json().put("routine",tasks);Alarm retained=Alarm.read(source);assertTrue(retained.routineInvalid);assertEquals(tasks.toString(),retained.json().getJSONArray("routine").toString());assertThrows(JSONException.class,()->Backup.restoreData(store,store.backup().put("alarms",new JSONArray().put(source).put(other.json()))));assertEquals(before,store.backup().toString());}JSONArray wrong=ChallengeRoutineJson.encode(saved.challenges());wrong.getJSONObject(0).put("code",valid);assertThrows(JSONException.class,()->ChallengeRoutineJson.decode(wrong));JSONArray multiple=ChallengeRoutineJson.encode(saved.challenges());multiple.getJSONObject(1).put("rounds",2);assertThrows(JSONException.class,()->ChallengeRoutineJson.decode(multiple));}
